<?php
namespace Modules\ProductsNew\Services\InventoryIntelligence;
use Illuminate\Support\Facades\DB;
use Modules\ProductsNew\Entities\InventoryPlanningProfile;
use Modules\ProductsNew\Entities\ReorderProposal;
use Modules\ProductsNew\Utilities\ProductsNewTenantGuard;
class InventoryPlanningService
{
    public function summary(array $filters=[]): array { $businessId=ProductsNewTenantGuard::businessId($filters['business_id']??null); $profiles=InventoryPlanningProfile::where('business_id',$businessId); $props=ReorderProposal::where('business_id',$businessId); return ['total_profiles'=>(clone $profiles)->count(),'active_profiles'=>(clone $profiles)->where('is_active',1)->count(),'pending_proposals'=>(clone $props)->where('status','pending')->count(),'estimated_reorder_value'=>(float)(clone $props)->where('status','pending')->sum('estimated_cost')]; }
    public function listProfiles(array $filters=[]) { $businessId=ProductsNewTenantGuard::businessId($filters['business_id']??null); return InventoryPlanningProfile::where('business_id',$businessId)->when(!empty($filters['location_id']),fn($q)=>$q->where('location_id',$filters['location_id']))->latest('id')->paginate($filters['per_page']??25); }
    public function saveProfile(array $data): InventoryPlanningProfile { $businessId=ProductsNewTenantGuard::businessId($data['business_id']??null); return InventoryPlanningProfile::updateOrCreate(['business_id'=>$businessId,'location_id'=>$data['location_id']??null,'product_id'=>$data['product_id'],'variation_id'=>$data['variation_id']??null],['minimum_qty'=>$data['minimum_qty']??0,'maximum_qty'=>$data['maximum_qty']??0,'safety_stock_qty'=>$data['safety_stock_qty']??0,'lead_time_days'=>$data['lead_time_days']??0,'seasonality_profile'=>$data['seasonality_profile']??null,'planning_method'=>$data['planning_method']??'manual','reorder_qty'=>$data['reorder_qty']??null,'is_active'=>$data['is_active']??1,'created_by'=>auth()->id(),'updated_by'=>auth()->id()]); }
    public function buildReorderProposals(array $filters=[]): int { $businessId=ProductsNewTenantGuard::businessId($filters['business_id']??null); $created=0; foreach(InventoryPlanningProfile::where('business_id',$businessId)->where('is_active',1)->get() as $profile){ $stock=(float)DB::table('variation_location_details')->where('product_id',$profile->product_id)->when($profile->variation_id,fn($q)=>$q->where('variation_id',$profile->variation_id))->when($profile->location_id,fn($q)=>$q->where('location_id',$profile->location_id))->sum('qty_available'); if($stock>((float)$profile->minimum_qty+(float)$profile->safety_stock_qty)){continue;} $qty=$profile->reorder_qty?:max(0,(float)$profile->maximum_qty-$stock); ReorderProposal::create(['business_id'=>$businessId,'location_id'=>$profile->location_id,'product_id'=>$profile->product_id,'variation_id'=>$profile->variation_id,'proposal_date'=>now()->toDateString(),'current_stock'=>$stock,'minimum_qty'=>$profile->minimum_qty,'maximum_qty'=>$profile->maximum_qty,'safety_stock_qty'=>$profile->safety_stock_qty,'lead_time_days'=>$profile->lead_time_days,'recommended_qty'=>$qty,'estimated_cost'=>0,'status'=>'pending','notes'=>'Auto generated by Products New inventory planning centre.','created_by'=>auth()->id()]); $created++; } return $created; }
}
